create table app_user (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, email varchar(180) not null unique, display_name varchar(100) not null, password_hash varchar(100) not null, role varchar(30) not null, organization_id uuid, team_id uuid, enabled boolean not null, last_login_at timestamptz);
create table organization (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, name varchar(120) not null, plan varchar(50) not null, status varchar(20) not null, health varchar(20) not null, health_score integer not null check(health_score between 0 and 100), owner_id uuid not null references app_user(id), renewal_date date not null, billing_email varchar(180) not null, risk_summary varchar(500) not null);
create table contact (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, organization_id uuid not null references organization(id), name varchar(100) not null, email varchar(180) not null, phone varchar(40), title varchar(100), billing_contact boolean not null, portal_access boolean not null);
create table deal (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, organization_id uuid not null references organization(id), name varchar(140) not null, stage varchar(30) not null, value numeric(15,2) not null check(value>=0), currency varchar(3) not null, probability integer not null check(probability between 0 and 100), close_date date not null, notes varchar(2000) not null);
create table escalation (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, organization_id uuid not null references organization(id), subject varchar(160) not null, severity varchar(20) not null, status varchar(30) not null, assigned_agent_id uuid references app_user(id), team_id uuid, customer_summary varchar(2000) not null, status_changed_at timestamptz not null);
create table escalation_comment (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, escalation_id uuid not null references escalation(id) on delete cascade, author_id uuid not null references app_user(id), internal_only boolean not null, body varchar(4000) not null);
create table customer_document (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, organization_id uuid not null references organization(id), uploaded_by uuid not null references app_user(id), display_name varchar(180) not null, stored_name varchar(180) not null unique, content_type varchar(120) not null, size_bytes bigint not null, category varchar(40) not null, visibility varchar(30) not null, tags varchar(300) not null);
create table api_credential (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, organization_id uuid not null references organization(id), label varchar(100) not null, prefix varchar(20) not null unique, secret_hash varchar(100) not null, scopes varchar(300) not null, status varchar(20) not null, last_used_at timestamptz, expires_at timestamptz);
create table webhook_endpoint (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, organization_id uuid not null references organization(id), name varchar(120) not null, url varchar(500) not null, events varchar(500) not null, secret_hash varchar(100) not null, enabled boolean not null);
create table webhook_delivery (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, webhook_id uuid not null references webhook_endpoint(id), request_url varchar(500) not null, event_type varchar(60) not null, result varchar(30) not null, response_summary varchar(500) not null);
create table audit_event (id uuid primary key, occurred_at timestamptz not null, actor_id uuid not null references app_user(id), action varchar(80) not null, resource_type varchar(80) not null, resource_id uuid, before_value text not null, after_value text not null, authorization_basis varchar(300) not null);
create table notification (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, user_id uuid not null references app_user(id), title varchar(120) not null, message varchar(500) not null, target_route varchar(300) not null, read_flag boolean not null);
create table invite_token (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, token_hash varchar(100) not null unique, email varchar(180) not null, organization_id uuid not null references organization(id), expires_at timestamptz not null, used_at timestamptz);
create table password_reset_token (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, token_hash varchar(100) not null unique, user_id uuid not null references app_user(id), expires_at timestamptz not null, used_at timestamptz);
create table outbox_message (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, recipient varchar(180) not null, subject varchar(180) not null, body text not null, status varchar(20) not null);
create table plan_definition (id uuid primary key, version bigint not null, created_at timestamptz not null, updated_at timestamptz not null, name varchar(50) not null unique, monthly_price numeric(12,2) not null, currency varchar(3) not null, api_rate_limit integer not null, user_limit integer not null);
create index idx_org_owner on organization(owner_id); create index idx_contact_org on contact(organization_id); create index idx_deal_org on deal(organization_id); create index idx_esc_org on escalation(organization_id); create index idx_esc_assignee on escalation(assigned_agent_id); create index idx_doc_org on customer_document(organization_id); create index idx_audit_time on audit_event(occurred_at desc); create index idx_notification_user on notification(user_id,read_flag);

create or replace function prevent_audit_mutation() returns trigger language plpgsql as $$ begin raise exception 'audit events are append-only'; end $$;
create trigger audit_no_update before update or delete on audit_event for each row execute function prevent_audit_mutation();
